using Leads.Application.DTOs; using Leads.Application.Ports; using Leads.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace Leads.Infrastructure.Repositories;
public sealed class AdvisorRepository(LeadsDbContext db):IAdvisorRepository{public async Task<IReadOnlyList<AdvisorDto>> ListAsync(long? e,long? p,bool? a,CancellationToken ct){var q=db.Advisors.AsNoTracking().AsQueryable();if(e.HasValue)q=q.Where(x=>x.EmpresaId==e);if(p.HasValue)q=q.Where(x=>x.PuntoVentaId==p);if(a.HasValue)q=q.Where(x=>x.Activo==a);return await q.OrderBy(x=>x.Nombre).Select(x=>new AdvisorDto(x.AsesorId,x.Nombre,x.PuntoVentaId,x.EmpresaId,x.CapacidadDiariaLeads,x.Activo)).ToListAsync(ct);}}
public sealed class MotorcycleRepository(LeadsDbContext db):IMotorcycleRepository{public async Task<IReadOnlyList<MotorcycleDto>> ListAsync(string? m,string? s,CancellationToken ct){var q=db.Motorcycles.AsNoTracking().AsQueryable();if(!string.IsNullOrWhiteSpace(m))q=q.Where(x=>x.Marca==m);if(!string.IsNullOrWhiteSpace(s))q=q.Where(x=>x.Segmento==s);return await q.OrderBy(x=>x.Marca).ThenBy(x=>x.Linea).Select(x=>new MotorcycleDto(x.Sku,x.Marca,x.Linea,x.Cilindraje,x.Segmento,x.PrecioLista,x.PuntosVentaDisponibles,x.UnidadesDisponibles)).ToListAsync(ct);}}
public sealed class PipelineRunRepository(LeadsDbContext db):IPipelineRunRepository{public async Task<IReadOnlyList<PipelineRunDto>> ListAsync(int page,int size,CancellationToken ct)=>await db.PipelineRuns.AsNoTracking().OrderByDescending(x=>x.StartedAt).Skip(Math.Max(0,page-1)*Math.Clamp(size,1,100)).Take(Math.Clamp(size,1,100)).Select(x=>new PipelineRunDto(x.RunId,x.Status,x.StartedAt,x.FinishedAt,x.SummaryJson,x.Error)).ToListAsync(ct);}
